import { request, CLIPBOARD_SYNC_BASE_URL } from './http';

export function listClipboardItems() {
  return request(CLIPBOARD_SYNC_BASE_URL, '/clipboard/items', {
    auth: true,
  });
}

export function createClipboardItem(content) {
  return request(CLIPBOARD_SYNC_BASE_URL, '/clipboard/items', {
    method: 'POST',
    body: { content },
    auth: true,
  });
}

export function deleteClipboardItem(itemId) {
  return request(CLIPBOARD_SYNC_BASE_URL, `/clipboard/items/${itemId}`, {
    method: 'DELETE',
    auth: true,
  });
}
