<template>
  <section class="view-shell">
    <header class="view-header">
      <div>
        <h2>个人云盘</h2>
        <p>上传、下载和整理当前账号的私有文件。</p>
      </div>
      <div class="toolbar">
        <input ref="fileInput" class="hidden-input" type="file" @change="handleFileSelected" />
        <el-button type="primary" icon="el-icon-upload2" :loading="uploading" @click="pickFile">
          上传
        </el-button>
        <el-button icon="el-icon-folder-add" @click="promptCreateFolder">新建文件夹</el-button>
        <el-button icon="el-icon-refresh" :loading="loading" @click="refresh">刷新</el-button>
      </div>
    </header>

    <div class="drive-card">
      <el-breadcrumb separator-class="el-icon-arrow-right" class="drive-path">
        <el-breadcrumb-item
          v-for="item in path"
          :key="item.id"
        >
          <button class="path-button" type="button" @click="openFolder(item.id)">
            {{ item.name === '涓汉浜戠洏' ? '个人云盘' : item.name }}
          </button>
        </el-breadcrumb-item>
      </el-breadcrumb>

      <el-table
        v-loading="loading"
        :data="files"
        empty-text="当前目录为空"
        @row-dblclick="handleRowDblClick"
      >
        <el-table-column label="名称" min-width="260">
          <template slot-scope="{ row }">
            <span class="file-name">
              <i :class="row.is_dir ? 'el-icon-folder' : 'el-icon-document'"></i>
              {{ row.name }}
            </span>
          </template>
        </el-table-column>
        <el-table-column label="大小" width="120">
          <template slot-scope="{ row }">
            {{ row.is_dir ? '-' : formatSize(row.size) }}
          </template>
        </el-table-column>
        <el-table-column label="创建时间" width="190">
          <template slot-scope="{ row }">
            {{ formatDate(row.created_at) }}
          </template>
        </el-table-column>
        <el-table-column label="操作" width="260" align="right">
          <template slot-scope="{ row }">
            <el-tooltip content="打开" placement="top" v-if="row.is_dir">
              <el-button icon="el-icon-folder-opened" circle size="mini" @click="openFolder(row.id)"></el-button>
            </el-tooltip>
            <el-tooltip content="下载" placement="top" v-else>
              <el-button icon="el-icon-download" circle size="mini" @click="download(row)"></el-button>
            </el-tooltip>
            <el-tooltip content="重命名" placement="top">
              <el-button icon="el-icon-edit" circle size="mini" @click="promptRename(row)"></el-button>
            </el-tooltip>
            <el-tooltip content="删除" placement="top">
              <el-button
                icon="el-icon-delete"
                circle
                size="mini"
                type="danger"
                @click="confirmDelete(row)"
              ></el-button>
            </el-tooltip>
          </template>
        </el-table-column>
      </el-table>
    </div>
  </section>
</template>

<script>
import {
  createFolder,
  deleteItem,
  downloadFile,
  getPath,
  listFiles,
  renameItem,
  uploadFile,
} from '@/api/personalDrive';
import { formatDate, formatSize, saveBlob } from '@/utils/file';

export default {
  name: 'PersonalDrive',
  data() {
    return {
      loading: false,
      uploading: false,
      parentId: 0,
      files: [],
      path: [],
    };
  },
  mounted() {
    this.refresh();
  },
  methods: {
    formatDate,
    formatSize,
    async refresh() {
      this.loading = true;
      try {
        const [files, path] = await Promise.all([
          listFiles(this.parentId),
          getPath(this.parentId),
        ]);
        this.files = files;
        this.path = path;
      } catch (error) {
        this.$message.error(error.message || '云盘加载失败');
      } finally {
        this.loading = false;
      }
    },
    openFolder(folderId) {
      this.parentId = folderId;
      this.refresh();
    },
    handleRowDblClick(row) {
      if (row.is_dir) {
        this.openFolder(row.id);
      }
    },
    pickFile() {
      this.$refs.fileInput.click();
    },
    async handleFileSelected(event) {
      const [file] = event.target.files;
      if (!file) return;

      this.uploading = true;
      try {
        await uploadFile(this.parentId, file);
        this.$message.success('上传成功');
        await this.refresh();
      } catch (error) {
        this.$message.error(error.message || '上传失败');
      } finally {
        this.uploading = false;
        event.target.value = '';
      }
    },
    async promptCreateFolder() {
      try {
        const { value } = await this.$prompt('请输入文件夹名称', '新建文件夹', {
          inputPattern: /^.{1,80}$/,
          inputErrorMessage: '名称不能为空，且最多 80 个字符',
        });
        await createFolder(this.parentId, value);
        this.$message.success('文件夹已创建');
        await this.refresh();
      } catch (error) {
        if (error !== 'cancel') {
          this.$message.error(error.message || '创建失败');
        }
      }
    },
    async promptRename(row) {
      try {
        const { value } = await this.$prompt('请输入新名称', '重命名', {
          inputValue: row.name,
          inputPattern: /^.{1,120}$/,
          inputErrorMessage: '名称不能为空，且最多 120 个字符',
        });
        await renameItem(row.id, value);
        this.$message.success('重命名成功');
        await this.refresh();
      } catch (error) {
        if (error !== 'cancel') {
          this.$message.error(error.message || '重命名失败');
        }
      }
    },
    async confirmDelete(row) {
      try {
        await this.$confirm(`确定删除「${row.name}」吗？`, '删除确认', {
          type: 'warning',
        });
        await deleteItem(row.id);
        this.$message.success('删除成功');
        await this.refresh();
      } catch (error) {
        if (error !== 'cancel') {
          this.$message.error(error.message || '删除失败');
        }
      }
    },
    async download(row) {
      try {
        const blob = await downloadFile(row.id);
        saveBlob(blob, row.name);
      } catch (error) {
        this.$message.error(error.message || '下载失败');
      }
    },
  },
};
</script>

