<template>
  <section class="view-shell">
    <header class="view-header">
      <div>
        <h2>用户资料</h2>
        <p>维护个人信息，供桌面端和网页端共享。</p>
      </div>
      <el-button icon="el-icon-refresh" :loading="loading" @click="loadProfile">刷新</el-button>
    </header>

    <div class="profile-layout">
      <aside class="profile-summary">
        <img v-if="avatarSrc" class="profile-avatar" :src="avatarSrc" alt="avatar" />
        <div v-else class="profile-avatar fallback">{{ username.slice(0, 1).toUpperCase() }}</div>
        <h3>{{ form.name || username }}</h3>
        <p>{{ form.motto || '还没有签名' }}</p>
      </aside>

      <el-form
        ref="profileForm"
        class="profile-form"
        :model="form"
        :rules="rules"
        label-width="88px"
      >
        <el-form-item label="用户名">
          <el-input v-model="username" disabled></el-input>
        </el-form-item>
        <el-form-item label="昵称" prop="name">
          <el-input v-model.trim="form.name" placeholder="展示名称"></el-input>
        </el-form-item>
        <el-form-item label="签名" prop="motto">
          <el-input v-model.trim="form.motto" placeholder="一句话介绍自己"></el-input>
        </el-form-item>
        <el-form-item label="性别" prop="gender">
          <el-select v-model="form.gender" placeholder="请选择">
            <el-option label="男" value="Male"></el-option>
            <el-option label="女" value="Female"></el-option>
            <el-option label="其他" value="Other"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="生日" prop="birthday">
          <el-date-picker
            v-model="form.birthday"
            type="date"
            value-format="yyyy-MM-dd"
            placeholder="选择日期"
          ></el-date-picker>
        </el-form-item>
        <el-form-item label="所在地">
          <el-input v-model.trim="form.location" placeholder="城市或地区"></el-input>
        </el-form-item>
        <el-form-item label="公司">
          <el-input v-model.trim="form.company" placeholder="公司 / 组织"></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" icon="el-icon-check" :loading="saving" @click="saveProfile">
            保存资料
          </el-button>
        </el-form-item>
      </el-form>
    </div>
  </section>
</template>

<script>
import { getUserInfo, updateUserInfo } from '@/api/userInfo';

export default {
  name: 'UserProfile',
  props: {
    session: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      loading: false,
      saving: false,
      avatarBase64: '',
      form: {
        name: '',
        motto: '',
        gender: 'Other',
        birthday: '',
        location: '',
        company: '',
      },
      rules: {
        birthday: [{ required: true, message: '请选择生日', trigger: 'change' }],
        gender: [{ required: true, message: '请选择性别', trigger: 'change' }],
      },
    };
  },
  computed: {
    username() {
      return this.session.username || '';
    },
    avatarSrc() {
      return this.avatarBase64 ? `data:image/png;base64,${this.avatarBase64}` : '';
    },
  },
  mounted() {
    this.loadProfile();
  },
  methods: {
    async loadProfile() {
      if (!this.username) return;

      this.loading = true;
      try {
        const data = await getUserInfo(this.username);
        this.form = {
          name: data.name || '',
          motto: data.motto || '',
          gender: data.gender || 'Other',
          birthday: data.birthday || '',
          location: data.location || '',
          company: data.company || '',
        };
        this.avatarBase64 = data.avator_base64 || '';
      } catch (error) {
        this.$message.error(error.message || '资料加载失败');
      } finally {
        this.loading = false;
      }
    },
    async saveProfile() {
      this.$refs.profileForm.validate(async (valid) => {
        if (!valid) return;

        this.saving = true;
        try {
          await updateUserInfo({
            username: this.username,
            ...this.form,
          });
          this.$message.success('资料已保存');
        } catch (error) {
          this.$message.error(error.message || '资料保存失败');
        } finally {
          this.saving = false;
        }
      });
    },
  },
};
</script>

