import { request, USERINFO_BASE_URL } from './http';

export function login(payload) {
  return request(USERINFO_BASE_URL, '/user/login', {
    method: 'POST',
    body: payload,
  });
}

export function register(payload) {
  return request(USERINFO_BASE_URL, '/user/register', {
    method: 'POST',
    body: payload,
  });
}

export function getMe() {
  return request(USERINFO_BASE_URL, '/user/me', {
    auth: true,
  });
}

export function getUserInfo(username) {
  return request(USERINFO_BASE_URL, '/info/get_user_info', {
    method: 'POST',
    body: { username },
  });
}

export function updateUserInfo(payload) {
  return request(USERINFO_BASE_URL, '/info/update_user_info', {
    method: 'POST',
    body: payload,
  });
}
