import {
  getAccessToken,
  getRefreshToken,
  updateSession,
  clearSession,
} from '@/utils/session';

export const USERINFO_BASE_URL = process.env.VUE_APP_USERINFO_API || '/user-api';
export const PERSONAL_DRIVE_BASE_URL = process.env.VUE_APP_PERSONALDRIVE_API || '/drive-api';
export const CLIPBOARD_SYNC_BASE_URL = process.env.VUE_APP_CLIPBOARD_SYNC_API || '/clipboard-api';

async function parseResponse(response, responseType) {
  if (responseType === 'blob') {
    return response.blob();
  }

  const text = await response.text();
  if (!text) return null;

  try {
    return JSON.parse(text);
  } catch (error) {
    return text;
  }
}

function buildHeaders(options) {
  const headers = new Headers(options.headers || {});

  if (options.auth) {
    const token = getAccessToken();
    if (token) headers.set('Authorization', `Bearer ${token}`);
  }

  if (options.body && !(options.body instanceof FormData) && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }

  return headers;
}

async function refreshAccessToken() {
  const refreshToken = getRefreshToken();
  if (!refreshToken) return null;

  const response = await fetch(`${USERINFO_BASE_URL}/user/refresh`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${refreshToken}`,
    },
  });

  if (!response.ok) {
    clearSession();
    return null;
  }

  const data = await response.json();
  updateSession({ access_token: data.access_token, username: data.username });
  return data.access_token;
}

export async function request(baseUrl, path, options = {}) {
  const requestOptions = {
    method: options.method || 'GET',
    headers: buildHeaders(options),
    body: options.body instanceof FormData
      ? options.body
      : options.body
        ? JSON.stringify(options.body)
        : undefined,
  };

  const response = await fetch(`${baseUrl}${path}`, requestOptions);

  if (response.status === 401 && options.auth && !options._retried) {
    const token = await refreshAccessToken();
    if (token) {
      return request(baseUrl, path, { ...options, _retried: true });
    }
  }

  const data = await parseResponse(response, options.responseType);

  if (!response.ok) {
    const message = data && (data.message || data.msg || data.error)
      ? data.message || data.msg || data.error
      : `Request failed with status ${response.status}`;
    const error = new Error(message);
    error.status = response.status;
    error.data = data;
    throw error;
  }

  return data;
}
